CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'owner', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, blocked_until timestamptz);
CREATE TABLE settings (user_id uuid PRIMARY KEY REFERENCES users, studio_name text NOT NULL DEFAULT 'AI Artist Studio', timezone text NOT NULL DEFAULT 'Europe/Berlin', provider text NOT NULL DEFAULT 'codex', mode text NOT NULL DEFAULT 'assisted', emergency_stop boolean NOT NULL DEFAULT false, daily_ai_limit integer NOT NULL DEFAULT 30 CHECK(daily_ai_limit>=0), monthly_ai_limit integer NOT NULL DEFAULT 300 CHECK(monthly_ai_limit>=0), daily_render_limit integer NOT NULL DEFAULT 20, storage_limit_mb integer NOT NULL DEFAULT 10240, daily_cost_limit numeric NOT NULL DEFAULT 0, monthly_cost_limit numeric NOT NULL DEFAULT 0, retention_days integer NOT NULL DEFAULT 365, setup_step integer NOT NULL DEFAULT 1);
CREATE TABLE artists (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, name text NOT NULL, bio text NOT NULL DEFAULT '', language text NOT NULL DEFAULT 'Deutsch', market text NOT NULL DEFAULT 'DACH', genre text NOT NULL DEFAULT '', color text NOT NULL DEFAULT '#ff875d', identity jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity_versions (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, version integer NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(artist_id,version));
CREATE TABLE ideas (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, title text NOT NULL, premise text NOT NULL DEFAULT '', conflict text NOT NULL DEFAULT '', hook text NOT NULL DEFAULT '', direction text NOT NULL DEFAULT '', video_idea text NOT NULL DEFAULT '', rationale text NOT NULL DEFAULT '', sources jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'proposed', feedback text NOT NULL DEFAULT '', similarity numeric, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE songs (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, idea_id uuid REFERENCES ideas ON DELETE SET NULL, identity_version integer NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lyrics_versions (id uuid PRIMARY KEY, song_id uuid NOT NULL REFERENCES songs ON DELETE CASCADE, version integer NOT NULL, title text NOT NULL, lyrics text NOT NULL, style_prompt text NOT NULL DEFAULT '', negative_prompt text NOT NULL DEFAULT '', pronunciation text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', hooks jsonb NOT NULL DEFAULT '[]', protected_lines jsonb NOT NULL DEFAULT '[]', source text NOT NULL DEFAULT 'human', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(song_id,version));
CREATE TABLE music_orders (id uuid PRIMARY KEY, song_id uuid NOT NULL REFERENCES songs ON DELETE CASCADE, lyrics_version_id uuid NOT NULL REFERENCES lyrics_versions, production_number text UNIQUE NOT NULL, provider text NOT NULL DEFAULT 'suno_manual', state text NOT NULL DEFAULT 'waiting_for_input', package jsonb NOT NULL, external_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, song_id uuid REFERENCES songs ON DELETE SET NULL, parent_id uuid REFERENCES assets ON DELETE SET NULL, kind text NOT NULL, name text NOT NULL, storage_key text UNIQUE NOT NULL, mime text NOT NULL, bytes bigint NOT NULL, sha256 text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', origin text NOT NULL DEFAULT 'upload', rights_status text NOT NULL DEFAULT 'unclear', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rights_records (id uuid PRIMARY KEY, asset_id uuid NOT NULL REFERENCES assets ON DELETE CASCADE, status text NOT NULL, provider text NOT NULL DEFAULT '', plan text NOT NULL DEFAULT '', input_origin text NOT NULL DEFAULT '', acquisition text NOT NULL DEFAULT '', terms_url text NOT NULL DEFAULT '', terms_date text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', evidence_asset_id uuid REFERENCES assets ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artist_references (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, asset_id uuid NOT NULL REFERENCES assets ON DELETE CASCADE, type text NOT NULL, notes text NOT NULL DEFAULT '', state text NOT NULL DEFAULT 'proposed', identity_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audio_variants (id uuid PRIMARY KEY, song_id uuid NOT NULL REFERENCES songs ON DELETE CASCADE, asset_id uuid NOT NULL REFERENCES assets ON DELETE CASCADE, order_id uuid REFERENCES music_orders, lyrics_version_id uuid REFERENCES lyrics_versions, label text NOT NULL, external_url text NOT NULL DEFAULT '', external_id text NOT NULL DEFAULT '', generated_at timestamptz, generation_info jsonb NOT NULL DEFAULT '{}', is_master boolean NOT NULL DEFAULT false, clip_start numeric NOT NULL DEFAULT 0, clip_end numeric, notes text NOT NULL DEFAULT '', markers jsonb NOT NULL DEFAULT '[]', timings jsonb NOT NULL DEFAULT '[]', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_master_per_song ON audio_variants(song_id) WHERE is_master;
CREATE TABLE video_projects (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, song_id uuid NOT NULL REFERENCES songs ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES audio_variants, name text NOT NULL, template text NOT NULL CHECK(template IN ('character','scenes','visualizer')), timeline jsonb NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE renders (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES video_projects ON DELETE CASCADE, project_version integer NOT NULL, snapshot jsonb NOT NULL, state text NOT NULL DEFAULT 'queued', progress integer NOT NULL DEFAULT 0, asset_id uuid REFERENCES assets ON DELETE SET NULL, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaigns (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, song_id uuid REFERENCES songs ON DELETE SET NULL, name text NOT NULL, goal text NOT NULL DEFAULT '', budget numeric NOT NULL DEFAULT 0, concepts jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_accounts (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, platform text NOT NULL DEFAULT 'tiktok', label text NOT NULL, external_id text, scopes text[] NOT NULL DEFAULT '{}', access_token text, refresh_token text, expires_at timestamptz, status text NOT NULL DEFAULT 'manual', last_sync_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE posts (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, campaign_id uuid REFERENCES campaigns ON DELETE SET NULL, song_id uuid REFERENCES songs ON DELETE SET NULL, account_id uuid NOT NULL REFERENCES social_accounts, asset_id uuid NOT NULL REFERENCES assets, cover_id uuid REFERENCES assets, title text NOT NULL, caption text NOT NULL DEFAULT '', hashtags text NOT NULL DEFAULT '', is_aigc boolean NOT NULL DEFAULT true, commercial boolean NOT NULL DEFAULT false, privacy text NOT NULL DEFAULT 'SELF_ONLY', interactions jsonb NOT NULL DEFAULT '{"comment":false,"duet":false,"stitch":false}', rights_note text NOT NULL DEFAULT '', scheduled_at timestamptz, timezone text NOT NULL DEFAULT 'Europe/Berlin', status text NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1, published_url text, published_at timestamptz, verification text, external_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approvals (id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts ON DELETE CASCADE, snapshot jsonb NOT NULL, snapshot_hash text NOT NULL, state text NOT NULL DEFAULT 'approved', user_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publication_attempts (id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts ON DELETE CASCADE, approval_id uuid REFERENCES approvals, idempotency_key text UNIQUE NOT NULL, state text NOT NULL, external_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE comments (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, account_id uuid REFERENCES social_accounts, post_id uuid REFERENCES posts ON DELETE SET NULL, external_id text, author text NOT NULL DEFAULT 'Anonym', body text NOT NULL, source text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'new', category text, imported_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,external_id));
CREATE TABLE reply_drafts (id uuid PRIMARY KEY, comment_id uuid NOT NULL REFERENCES comments ON DELETE CASCADE, body text NOT NULL, state text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE metric_snapshots (id uuid PRIMARY KEY, post_id uuid NOT NULL REFERENCES posts ON DELETE CASCADE, metric text NOT NULL, value numeric CHECK(value>=0), unit text NOT NULL DEFAULT 'count', source text NOT NULL, captured_at timestamptz NOT NULL, period_start timestamptz, period_end timestamptz, quality text NOT NULL DEFAULT 'manual', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE insights (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, claim text NOT NULL, rationale text NOT NULL, uncertainty text NOT NULL, proposed_test text NOT NULL, data_refs jsonb NOT NULL DEFAULT '[]', valid_until timestamptz, rating text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE experiments (id uuid PRIMARY KEY, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, insight_id uuid REFERENCES insights, name text NOT NULL, hypothesis text NOT NULL, plan text NOT NULL, status text NOT NULL DEFAULT 'planned', result text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflows (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, artist_id uuid REFERENCES artists ON DELETE CASCADE, name text NOT NULL, state text NOT NULL DEFAULT 'queued', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, artist_id uuid REFERENCES artists ON DELETE CASCADE, workflow_id uuid REFERENCES workflows ON DELETE CASCADE, depends_on uuid REFERENCES jobs, kind text NOT NULL, state text NOT NULL DEFAULT 'queued', input jsonb NOT NULL DEFAULT '{}', output jsonb, progress integer NOT NULL DEFAULT 0, error text, attempt_count integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 2, idempotency_key text NOT NULL, side_effect text NOT NULL DEFAULT 'local', lease_until timestamptz, cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE job_attempts (id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs ON DELETE CASCADE, attempt integer NOT NULL, state text NOT NULL, error text, usage jsonb, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE outbox (id uuid PRIMARY KEY, job_id uuid NOT NULL UNIQUE REFERENCES jobs ON DELETE CASCADE, dispatched_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE budget_reservations (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, job_id uuid UNIQUE REFERENCES jobs ON DELETE CASCADE, kind text NOT NULL, units numeric NOT NULL, cost numeric, state text NOT NULL DEFAULT 'reserved', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_connections (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, provider text NOT NULL, state text NOT NULL, capabilities jsonb NOT NULL DEFAULT '{}', details jsonb NOT NULL DEFAULT '{}', checked_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,provider));
CREATE TABLE director_messages (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, artist_id uuid REFERENCES artists ON DELETE CASCADE, role text NOT NULL, body text NOT NULL, action jsonb, job_id uuid REFERENCES jobs, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE oauth_states (state_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, artist_id uuid NOT NULL REFERENCES artists ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE webhook_events (id text PRIMARY KEY, provider text NOT NULL, event text NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY, user_id uuid REFERENCES users ON DELETE SET NULL, action text NOT NULL, object_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_pending ON jobs(state,created_at);
CREATE INDEX assets_artist ON assets(artist_id);
CREATE INDEX metrics_latest ON metric_snapshots(post_id,metric,captured_at DESC);
CREATE INDEX audit_user ON audit_events(user_id,created_at DESC);
